// Writes src/races.gen.ts: every race model in data/races, bundled into the Worker
// (Phase 4 spec A2). CI checks the generated file is up to date.
//   pnpm --filter @boxthislap/worker races
import { readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const races = join(here, '..', '..', '..', 'data', 'races');
const ids = readdirSync(races)
  .filter((f) => f.endsWith('.json'))
  .map((f) => f.slice(0, -'.json'.length))
  .sort();

const lines = [
  '// Generated by `pnpm --filter @boxthislap/worker races` from data/races. Do not edit.',
  '',
  ...ids.map((id, i) => `import r${i} from '../../../data/races/${id}.json';`),
  '',
  'export const RACE_FILES: Record<string, unknown> = {',
  ...ids.map((id, i) => `  '${id}': r${i},`),
  '};',
  '',
];
writeFileSync(join(here, '..', 'src', 'races.gen.ts'), lines.join('\n'));
console.log(`bundled ${ids.length} races`);
